<script setup>
import { computed,onMounted,ref } from 'vue'
import { api } from './api'
const broadcasts=ref([]),bots=ref([]),audience=ref([]),fields=ref([]),selected=ref(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const form=ref({name:'',channel_account_id:'',message_text:'',audience_type:'all',contact_ids:[],scheduled_at:'',parse_mode:'HTML',media_url:'',media_type:'image',stagger_seconds:0.05})
const editingId=ref(null)
const composerOpen=ref(false)
const showEmoji=ref(false)
const emojis=['😀','😃','😄','😁','😊','🙂','😉','😍','🥰','😘','😂','🤣','😅','😎','🤩','🥳','🤔','👍','👎','👏','🙌','🙏','💪','👌','✅','❌','⚠️','❤️','💚','💙','🔥','⭐','🎉','🎁','📣','📌','📅','⏰','💬','📞','📧','🔗','🚀','✨']
const recipientCount=computed(()=>form.value.audience_type==='all'?audience.value.length:form.value.contact_ids.length)
const activeBots=computed(()=>(bots.value||[]).filter(b=>b.active))
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
async function load(){loading.value=true;error.value='';try{[bots.value]=await Promise.all([api.telegramBots()]);if(!form.value.channel_account_id&&activeBots.value.length)form.value.channel_account_id=activeBots.value[0].id;await Promise.all([loadHistory(),loadAudience(),loadFields()])}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadHistory(){broadcasts.value=form.value.channel_account_id?await api.broadcasts('telegram',Number(form.value.channel_account_id)):[]}
async function loadFields(){fields.value=form.value.channel_account_id?await api.broadcastTelegramFields(Number(form.value.channel_account_id)):[]}
async function loadAudience(){audience.value=[];form.value.contact_ids=[];if(!form.value.channel_account_id)return;try{audience.value=await api.broadcastTelegramAudience(Number(form.value.channel_account_id))}catch(e){error.value=e.message}}
function localDateTime(v){if(!v)return '';const d=new Date(v),pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes())}
function resetForm(){editingId.value=null;form.value={name:'',channel_account_id:activeBots.value[0]?.id||'',message_text:'',audience_type:'all',contact_ids:[],scheduled_at:'',parse_mode:'HTML',media_url:'',media_type:'image',stagger_seconds:0.05};loadAudience()}
function newBroadcast(){resetForm();composerOpen.value=true}
function closeComposer(){composerOpen.value=false;showEmoji.value=false;resetForm()}
async function editBroadcast(){if(!selected.value||selected.value.status!=='draft')return;editingId.value=selected.value.id;form.value.name=selected.value.name;form.value.channel_account_id=selected.value.channel_account_id;form.value.message_text=selected.value.message_text;form.value.parse_mode=selected.value.parse_mode||'HTML';form.value.media_url=selected.value.media_url||'';form.value.media_type=selected.value.media_type||'image';form.value.stagger_seconds=selected.value.stagger_seconds||0.05;form.value.audience_type=selected.value.audience_type;form.value.scheduled_at=localDateTime(selected.value.scheduled_at);await loadAudience();if(form.value.audience_type==='selected')form.value.contact_ids=selected.value.recipients.map(r=>r.contact_id);composerOpen.value=true}
async function deleteBroadcast(){if(!selected.value||selected.value.status!=='draft'||!confirm('Delete this draft broadcast? This cannot be undone.'))return;error.value='';try{await api.deleteBroadcast(selected.value.id);selected.value=null;editingId.value=null;composerOpen.value=false;resetForm();await loadHistory();success.value='Draft broadcast deleted.'}catch(e){error.value=e.message}}
function insertEmoji(e){insertText(e);showEmoji.value=false}
function insertText(token){const el=document.querySelector('.broadcast-message');if(!el){form.value.message_text+=token;return}const start=el.selectionStart??form.value.message_text.length,end=el.selectionEnd??start;form.value.message_text=form.value.message_text.slice(0,start)+token+form.value.message_text.slice(end);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(start+token.length,start+token.length)})}
function insertField(key){const el=document.querySelector('.broadcast-message');const token='%'+key+'%';if(!el){form.value.message_text+=token;return}const start=el.selectionStart??form.value.message_text.length,end=el.selectionEnd??start;form.value.message_text=form.value.message_text.slice(0,start)+token+form.value.message_text.slice(end);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(start+token.length,start+token.length)})}
function wrap(open,close=open){const el=document.querySelector('.broadcast-message');if(!el)return;const s=el.selectionStart,e=el.selectionEnd,t=form.value.message_text;form.value.message_text=t.slice(0,s)+open+t.slice(s,e)+close+t.slice(e);requestAnimationFrame(()=>el.focus())}
function toggleAll(){form.value.contact_ids=form.value.contact_ids.length===audience.value.length?[]:audience.value.map(x=>x.id)}
async function createBroadcast(){if(saving.value)return;saving.value=true;error.value='';success.value='';try{const payload={...form.value,channel:'telegram',channel_account_id:Number(form.value.channel_account_id),scheduled_at:form.value.scheduled_at?new Date(form.value.scheduled_at).toISOString():null};const saved=editingId.value?await api.updateBroadcast(editingId.value,payload):await api.createBroadcast(payload);selected.value=await api.broadcast(saved.id);broadcasts.value=await api.broadcasts('telegram',Number(form.value.channel_account_id));success.value=editingId.value?'Draft broadcast updated.':'Draft created with '+saved.total_recipients+' recipient'+(saved.total_recipients===1?'':'s')+'.';editingId.value=null;composerOpen.value=false;resetForm()}catch(e){error.value=e.message}finally{saving.value=false}}
async function openBroadcast(row){error.value='';if(selected.value?.id===row.id){selected.value=null;return}try{selected.value=await api.broadcast(row.id)}catch(e){error.value=e.message}}
async function actOn(row,action){if(selected.value?.id!==row.id)selected.value=await api.broadcast(row.id);return action()}
async function queue(){if(!selected.value)return;error.value='';try{selected.value=await api.queueBroadcast(selected.value.id);broadcasts.value=await api.broadcasts('telegram',Number(form.value.channel_account_id));success.value=selected.value.status==='scheduled'?'Broadcast scheduled.':'Broadcast queued for delivery.'}catch(e){error.value=e.message}}
async function cancel(){if(!selected.value)return;error.value='';try{selected.value=await api.cancelBroadcast(selected.value.id);broadcasts.value=await api.broadcasts('telegram',Number(form.value.channel_account_id));success.value='Broadcast cancelled.'}catch(e){error.value=e.message}}
async function sendTest(r){error.value='';success.value='';try{await api.testBroadcast(selected.value.id,r.contact_id);success.value='Test message sent to '+(r.display_name||r.destination)+'.'}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template>
<section class="broadcast-page">
<header class="broadcast-head"><div><p class="eyebrow">Messaging</p><h1>Broadcasts</h1><p>Send Telegram messages to an audience of existing subscribers.</p></div><div class="head-actions"><button class="primary" @click="newBroadcast">+ New Broadcast Message</button><button class="secondary" @click="load">↻ Refresh</button></div></header>
<p v-if="error" class="broadcast-error">{{error}}</p><p v-if="success" class="broadcast-success">{{success}}</p>

<section class="broadcast-card list-card"><div class="list-title"><h2>Broadcast history</h2><span>{{broadcasts.length}} broadcast{{broadcasts.length===1?'':'s'}}</span></div>
<div v-if="loading">Loading…</div><div v-else-if="!broadcasts.length" class="empty">No broadcasts yet. Create your first broadcast message.</div>
<template v-for="b in broadcasts" :key="b.id">
<div class="broadcast-row" :class="{active:selected?.id===b.id}" @click="openBroadcast(b)">
  <span class="row-main"><strong>{{b.name}}</strong><small>{{fmt(b.created_at)}} · Telegram</small></span>
  <span class="row-metric"><strong>{{b.total_recipients}}</strong><small>Recipients</small></span>
  <span class="row-metric"><strong>{{b.sent_count}}</strong><small>Sent</small></span>
  <span class="row-metric"><strong>{{b.failed_count}}</strong><small>Failed</small></span>
  <span class="row-status"><b class="status">{{b.status}}</b><small v-if="b.scheduled_at">{{fmt(b.scheduled_at)}}</small></span>
  <span class="row-actions" @click.stop>
    <button v-if="b.status==='draft'" class="small-btn" @click="actOn(b,editBroadcast)">Edit</button>
    <button v-if="b.status==='draft'" class="small-btn primary" @click="actOn(b,queue)">{{b.scheduled_at?'Schedule':'Send now'}}</button>
    <button v-if="b.status==='draft'" class="small-btn danger" @click="actOn(b,deleteBroadcast)">Delete</button>
    <button v-if="!['draft','completed','cancelled','failed'].includes(b.status)" class="small-btn" @click="actOn(b,cancel)">Pause / Cancel</button>
    <button class="small-btn" @click="openBroadcast(b)">Stats</button>
  </span>
  <span class="chevron">{{selected?.id===b.id?'⌃':'⌄'}}</span>
</div>
<div v-if="selected?.id===b.id" class="row-detail">
  <div class="metrics"><div><strong>{{selected.total_recipients}}</strong><span>Recipients</span></div><div><strong>{{selected.sent_count}}</strong><span>Sent</span></div><div><strong>{{selected.failed_count}}</strong><span>Failed</span></div></div>
  <div class="detail-columns"><div><h3>Message</h3><pre class="message-preview">{{selected.message_text}}</pre><p v-if="selected.media_url"><strong>Media:</strong> {{selected.media_type}} · {{selected.media_url}}</p><p v-if="selected.scheduled_at"><strong>Scheduled:</strong> {{fmt(selected.scheduled_at)}}</p></div>
  <div class="recipient-list"><h3>Recipients</h3><article v-for="r in selected.recipients" :key="r.id"><span><strong>{{r.display_name||r.destination}}</strong><small>{{r.destination}}</small></span><span><b class="status">{{r.status}}</b><button v-if="selected.status==='draft'" class="link-btn" @click="sendTest(r)">Send test</button></span><p v-if="r.last_error">{{r.last_error}}</p></article></div></div>
</div>
</template></section>

<div v-if="composerOpen" class="modal-backdrop" @click.self="closeComposer">
<form class="broadcast-card composer-modal" @submit.prevent="createBroadcast">
<div class="composer-title"><div><p class="eyebrow">{{editingId?'Edit draft':'New message'}}</p><h2>{{editingId?'Edit broadcast':'New Broadcast Message'}}</h2></div><button type="button" class="modal-close" @click="closeComposer">×</button></div>
<div class="composer-grid"><label>Name<input v-model="form.name" maxlength="150" required placeholder="September promotion"/></label><label>Channel<select disabled><option>Telegram</option></select></label></div>
<label>Telegram bot<select v-model="form.channel_account_id" required @change="loadHistory();loadAudience();loadFields()"><option disabled value="">Select bot…</option><option v-for="bot in activeBots" :key="bot.id" :value="bot.id">{{bot.first_name||bot.username||('Bot '+bot.id)}}{{bot.username?' (@'+bot.username+')':''}}</option></select></label>
<label>Audience<select v-model="form.audience_type"><option value="all">All subscribers</option><option value="selected">Selected subscribers</option></select></label>
<div v-if="form.audience_type==='selected'" class="audience-box"><div class="audience-tools"><strong>{{form.contact_ids.length}} selected</strong><button type="button" class="link-btn" @click="toggleAll">{{form.contact_ids.length===audience.length?'Clear all':'Select all'}}</button></div><label v-for="contact in audience" :key="contact.id" class="recipient-check"><input v-model="form.contact_ids" type="checkbox" :value="contact.id"/><span>{{contact.name}}<small v-if="contact.username">@{{contact.username}}</small></span></label></div>
<label>Message<div class="editor-tools"><button type="button" @click="wrap('<b>','</b>')"><b>B</b></button><button type="button" @click="wrap('<i>','</i>')"><i>I</i></button><button type="button" @click="wrap('<u>','</u>')"><u>U</u></button><button type="button" @click="wrap('<s>','</s>')"><s>S</s></button><button type="button" @click="wrap('<a href=&quot;https://example.com&quot;>','</a>')">🔗 Link</button><span class="emoji-wrap"><button type="button" @click="showEmoji=!showEmoji">😊 ▾</button><span v-if="showEmoji" class="emoji-picker"><button v-for="e in emojis" :key="e" type="button" @click="insertEmoji(e)">{{e}}</button></span></span><select @change="if($event.target.value){insertField($event.target.value);$event.target.value=''}"><option value="">Insert Field…</option><option v-for="field in fields" :key="field.key" :value="field.key">{{field.label}} (%{{field.key}}%)</option></select></div><textarea class="broadcast-message" v-model="form.message_text" maxlength="4096" rows="8" required placeholder="Hi %first_name%, ..."></textarea><small>Telegram rich text supported. Fields are rendered separately for every recipient.</small></label>
<div class="media-group"><label class="media-type">Media type<select v-model="form.media_type"><option value="image">Image</option><option value="video">Video</option><option value="file">File</option></select></label><label class="media-url">Image / media URL (optional)<input v-model="form.media_url" placeholder="https://…"/></label></div>
<label>Delivery speed<select v-model.number="form.stagger_seconds"><option :value="0.05">Normal (~20/sec)</option><option :value="0.5">Staggered (2/sec)</option><option :value="1">1 per second</option><option :value="3">1 every 3 seconds</option><option :value="6">1 every 6 seconds</option></select><small>Controls the pace of delivery across the whole broadcast. Applied by the background worker.</small></label>
<label>Schedule (optional)<input v-model="form.scheduled_at" type="datetime-local"/></label>
<div class="modal-footer"><div class="broadcast-summary"><strong>{{recipientCount}}</strong> recipient{{recipientCount===1?'':'s'}}</div><div><button type="button" class="secondary" @click="closeComposer">Cancel</button> <button class="primary" :disabled="saving||!recipientCount">{{saving?'Saving…':(editingId?'Save changes':'Create draft')}}</button></div></div>
</form></div>
</section>
</template>
<style scoped>
.broadcast-page{padding:28px;max-width:1500px;margin:0 auto;width:100%}.broadcast-head,.composer-title,.audience-tools,.list-title,.modal-footer{display:flex;justify-content:space-between;align-items:center;gap:16px}.broadcast-head h1,.broadcast-card h2{margin:.2rem 0}.broadcast-head p{margin:.25rem 0;color:#667085}.head-actions{display:flex;gap:10px}.broadcast-card{background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:20px;box-shadow:0 1px 2px rgba(16,24,40,.04)}.list-card{margin-top:22px}.list-title{padding-bottom:10px}.list-title>span{color:#667085}.broadcast-row{display:grid;grid-template-columns:minmax(220px,2fr) 90px 80px 80px 150px minmax(280px,auto) 24px;align-items:center;gap:12px;padding:14px 10px;border-top:1px solid #eaecf0;cursor:pointer}.broadcast-row:hover,.broadcast-row.active{background:#f8fafc}.row-main small,.row-metric small,.row-status small,.recipient-list small{display:block;color:#667085;font-weight:400}.row-metric{text-align:center}.row-metric strong{font-size:18px}.row-status{text-align:center}.row-actions{display:flex;justify-content:flex-end;gap:6px;flex-wrap:wrap}.chevron{color:#667085;font-size:18px}.row-detail{padding:18px 20px 24px;background:#fbfcfd;border-top:1px solid #eaecf0;border-bottom:1px solid #eaecf0}.detail-columns{display:grid;grid-template-columns:minmax(280px,1fr) minmax(320px,1fr);gap:28px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 18px}.metrics div{background:#fff;border:1px solid #eaecf0;border-radius:10px;padding:14px;display:grid}.metrics strong{font-size:24px}.metrics span{color:#667085;font-size:12px}.message-preview{white-space:pre-wrap;font:inherit;background:#fff;border:1px solid #eaecf0;padding:14px;border-radius:10px}.recipient-list article{display:flex;justify-content:space-between;gap:10px;border-top:1px solid #eee;padding:10px 0}.recipient-list article>span:last-of-type{text-align:right}.recipient-list p{color:#b42318}.status{text-transform:capitalize;font-size:12px;background:#f2f4f7;border-radius:999px;padding:4px 8px}.primary,.secondary,.link-btn,.small-btn{border-radius:8px;padding:9px 13px;cursor:pointer}.primary{background:#101828;color:#fff;border:1px solid #101828}.secondary,.small-btn{background:#fff;border:1px solid #d0d5dd}.small-btn{padding:6px 9px;font-size:12px}.small-btn.primary{background:#101828;color:#fff}.danger{background:#fff!important;color:#b42318!important;border:1px solid #f1b4b4!important}.link-btn{border:0;background:transparent;color:#475467;padding:3px}.modal-backdrop{position:fixed;inset:0;background:rgba(16,24,40,.55);z-index:1000;display:flex;align-items:flex-start;justify-content:center;padding:4vh 20px;overflow:auto}.composer-modal{width:min(760px,100%);display:grid;gap:14px;max-height:92vh;overflow:auto}.composer-modal label{display:grid;gap:6px;font-weight:600}.composer-modal input,.composer-modal select,.composer-modal textarea{width:100%;box-sizing:border-box;border:1px solid #d0d5dd;border-radius:8px;padding:10px 12px;font:inherit}.composer-modal small{display:block;color:#667085;font-weight:400}.composer-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.media-group{display:grid;grid-template-columns:150px minmax(0,1fr);gap:14px;align-items:end}.media-type,.media-url{min-width:0}.modal-close{border:0;background:transparent;font-size:28px;cursor:pointer;color:#667085}.editor-tools{display:flex;gap:6px;flex-wrap:wrap}.editor-tools button,.editor-tools select{width:auto!important;padding:6px 9px!important;background:#fff;border:1px solid #d0d5dd;border-radius:6px}.emoji-wrap{position:relative}.emoji-picker{position:absolute;z-index:20;top:calc(100% + 6px);left:0;width:max-content;max-width:280px;height:auto;max-height:240px;overflow-y:auto;display:grid;grid-template-columns:repeat(7,34px);grid-auto-rows:34px;gap:2px;padding:8px;background:#fff;border:1px solid #d0d5dd;border-radius:9px;box-shadow:0 8px 24px rgba(16,24,40,.15)}.emoji-picker button{width:34px!important;height:34px!important;min-width:34px;padding:0!important;display:flex;align-items:center;justify-content:center;border:0!important;border-radius:6px!important;font-size:18px;line-height:1;background:transparent!important}.emoji-picker button:hover{background:#f2f4f7!important}.audience-box{border:1px solid #e4e7ec;border-radius:8px;max-height:220px;overflow:auto;padding:10px}.recipient-check{display:flex!important;align-items:center;gap:9px!important;padding:6px}.recipient-check input{width:auto}.broadcast-summary{background:#f8fafc;border-radius:8px;padding:10px}.broadcast-error{color:#b42318}.broadcast-success{color:#067647}.eyebrow{text-transform:uppercase;font-size:11px;font-weight:700;color:#067647;letter-spacing:.08em}@media(max-width:1100px){.broadcast-row{grid-template-columns:minmax(180px,1fr) repeat(3,65px) 120px}.row-actions{grid-column:1/-1;justify-content:flex-start}.chevron{display:none}}@media(max-width:700px){.broadcast-head,.head-actions,.modal-footer{align-items:stretch;flex-direction:column}.broadcast-row{grid-template-columns:1fr 1fr}.row-main,.row-actions{grid-column:1/-1}.detail-columns,.composer-grid,.media-group{grid-template-columns:1fr}.modal-backdrop{padding:0}.composer-modal{border-radius:0;min-height:100vh;max-height:none}}
</style>